<table class="enterprise-table" <?=$stockFilters?'data-butchery-history="stocks"':''?> data-search-placeholder="Lot, article, type…"><thead><tr><th>Lot / article</th><th>Type</th><th>Physique</th><th>Réservé</th><th>Disponible</th><th>DLC</th><th>Statut</th><th>Détail</th></tr></thead><tbody>
<?php foreach($stockRows as $row):?><tr data-status="<?=e($row['status'])?>" data-type="<?=e($row['kind'])?>" data-date="<?=e($row['expiry_date'])?>" data-dlc="<?=e($row['dlc_state'])?>">
<td><strong><?=e($row['lot_number'])?></strong><small><?=e($row['item_name'])?></small></td><td><?=e($row['kind_label'])?></td>
<?php foreach(['quantity_kg','reserved_kg','available'] as $field):?><td data-order="<?=e($row[$field])?>"><?=e($kg($row[$field]))?></td><?php endforeach;?>
<td data-order="<?=e(strtotime($row['expiry_date']))?>"><span class="<?=$row['dlc_state']==='expired'?'butchery-stock-expired':($row['dlc_state']==='soon'?'butchery-stock-soon':'')?>"><?=e(date('d/m/Y',strtotime($row['expiry_date'])))?></span><?php if($row['dlc_state']==='soon'):?><small>Échéance proche</small><?php endif;?></td><td><span class="butchery-status"><?=e($stockLabels[$row['status']]??$row['status'])?></span></td><td><button class="btn-secondary" type="button" data-workspace-modal-open="<?=e('butchery-stock-'.$row['kind'].'-'.$row['id'])?>" aria-label="<?=e('Consulter '.$row['lot_number'])?>">Consulter</button></td></tr><?php endforeach;?></tbody></table>
